(x, y, t) => {
  const cx = 240, cy = 120;
  const wx1 = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10;
  const wy1 = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10;
  const sx = x+wx1, sy = y+wy1;
  const wx2 = Math.sin(sx*0.025-t*0.4)*8 + Math.cos(sy*0.03+t*0.3)*6;
  const wy2 = Math.cos(sx*0.022+t*0.35)*8 + Math.sin(sy*0.028-t*0.45)*6;
  const sx2 = sx+wx2, sy2 = sy+wy2;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+1)*50, 0.11, 2.1],
    [400+Math.cos(t*0.55+2)*60, 220+Math.sin(t*0.75+4)*40, 0.085, 1.8]
  ];
  let aS=0, iS=0, wS=0;
  for (const [sX,sY,f,sp] of src) {
    const d = Math.sqrt((sx2-sX)**2+(sy2-sY)**2);
    aS += Math.sin(d*f-t*sp);
    iS += Math.sin(d*f*0.7+t*sp*0.6+1.5);
    wS += Math.sin(d*f*1.3-t*sp*0.8+0.7);
  }
  const n=src.length, act=aS/n, inh=iS/n, w=wS/n;
  const bg = (Math.sin(sx2*0.04+sy2*0.025+t*0.8)+Math.sin(sx2*0.03-sy2*0.04+t*1.1))/2
    + Math.sin((sx2+sy2)*0.12+t*2.5)*0.2 + Math.sin((sx2-sy2)*0.1-t*2)*0.2
    + Math.sin(sx2*0.08+sy2*0.06+t*1.5)*0.15;
  const dist = Math.sqrt((sx2-cx)**2+(sy2-cy)**2);
  const ang = Math.atan2(sy2-cy, sx2-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4
    + Math.sin(dist*0.08-ang*2+t*0.8)*0.2;
  const r3 = Math.tanh((w-act*0.5+inh*0.3)*1.8);
  const reaction = Math.tanh((act-inh*0.7+bg*0.3+spiral+r3*0.2)*2.2);
  const cell = Math.tanh((Math.sin(sx2*0.15)*Math.sin(sy2*0.15)+Math.sin((sx2+sy2)*0.1+t)*0.5)*1.5)*0.3;
  const micro = Math.sin(sx2*0.4+sy2*0.35+t*3)*Math.sin(sx2*0.3-sy2*0.45-t*2.5)*0.08;
  const blend = reaction*0.65+cell*0.2+r3*0.1+micro;
  const v = blend*0.5+0.5;
  const pal = [[12,15,72],[18,60,100],[20,110,120],[25,155,115],[180,175,50],[210,140,55],[205,95,60],[165,50,70],[90,20,65],[35,15,55],[12,15,72]];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = 0.8+Math.sin(reaction*Math.PI)*0.2;
  const edge = Math.abs(reaction)>0.7?1.15:1.0;
  const vig = 1.0-Math.sqrt((x-cx)**2+(y-cy)**2)/350*0.3;
  return [
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge*vig)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge*vig)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge*vig)|0
  ];
}
